const NODE_FLAG_CONST: u32 = 1 << 1;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[cfg_attr(not(test), allow(dead_code))]
enum SourceImportPhase {
    Value,
    Type,
}

/// One exact local binding introduced by a supported default or named import.
