    fn identifier_initializer(fixture: &Fixture, source: usize, name: &str) -> NodeRef {
        let file = &fixture.files[source];
        file.parsed
            .arena
            .iter()
            .find_map(|(node, record)| {
                let NodeData::Identifier(identifier) = &record.data else {
                    return None;
                };
                if identifier.text != name {
                    return None;
                }
                let parent = record
                    .parent
                    .and_then(|parent| file.parsed.arena.get(parent))?;
                matches!(
                    &parent.data,
                    NodeData::VariableDeclaration(variable) if variable.initializer == Some(node)
                )
                .then_some(NodeRef::new(file.parsed.arena.id(), file.file, node))
            })
            .expect("fixture contains requested identifier initializer")
    }

    fn binding_symbol(plan: &SourceImportPlan, local: &str) -> SemanticSymbolId {
        plan.bindings
            .iter()
            .find(|binding| binding.local_text == local)
            .unwrap_or_else(|| panic!("missing import binding {local}"))
            .alias_symbol
    }

    fn direct_export(fixture: &Fixture, source: usize, name: &str) -> SemanticSymbolId {
        let bound = fixture.bound.get(&fixture.files[source].file).unwrap();
        let module = bound.symbol(bound.source_file()).unwrap();
        let exports = fixture.store.symbol(module).unwrap().exports().unwrap();
        fixture
            .store
            .symbol_table(exports)
            .unwrap()
            .get_source(name)
            .unwrap()
    }

    #[test]
    fn side_effect_and_empty_named_imports_do_not_allocate_alias_state() {
        for (source, type_only) in [
            (r#"import "./target";"#, false),
            (r#"import {} from "./target";"#, false),
            (r#"import type {} from "./target";"#, true),
        ] {
            let fixture = fixture(
                &[source, "export type Model = number;"],
                &[Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                }],
            );
            let before = store_state(&fixture.store);
            let plan = if type_only {
                fixture.plan_type_import(0, 0)
            } else {
                fixture.plan_import(0, 0)
            };
            assert!(plan.bindings.is_empty());
            assert_eq!(plan.module_specifier.file, fixture.files[0].file);
            assert_eq!(store_state(&fixture.store), before);
        }
    }

    #[test]
    fn side_effect_imports_retain_ambient_module_resolution_without_aliases() {
        let fixture = fixture_with_module_states(
            &[
                r#"import "ambient";"#,
                r#"declare module "ambient" { export interface Value {} }"#,
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
            &[CanonicalModuleState::External, CanonicalModuleState::Script],
        );
        let before = store_state(&fixture.store);
        let plan = fixture.plan_import(0, 0);
        let CanonicalModuleResolutionLookup::Resolved(resolved) =
            fixture.manifest.lookup(plan.module_specifier)
        else {
            panic!("expected the side-effect import to retain its ambient module target")
        };
        let ambient_file = &fixture.files[1];
        let declaration = ambient_file
            .parsed
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ModuleDeclaration).then_some(NodeRef::new(
                    ambient_file.parsed.arena.id(),
                    ambient_file.file,
                    node,
                ))
            })
            .unwrap();
        let ambient = fixture
            .bound
            .get(&ambient_file.file)
            .and_then(|bound| bound.symbol(declaration))
            .unwrap();

        assert!(plan.bindings.is_empty());
        assert!(resolved.is_ambient_module());
        assert_eq!(resolved.target_symbol(), ambient);
        assert_eq!(store_state(&fixture.store), before);
    }

    #[test]
    fn empty_value_and_type_reexports_preserve_module_provenance_without_aliases() {
        for source in [
            r#"export {} from "./target";"#,
            "export { } from\n './target';",
            r#"export type {} from "./target";"#,
        ] {
            let fixture = fixture(
                &[source, "export const value: number = 1;"],
                &[Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                }],
            );
            let before = store_state(&fixture.store);
            let source_file = &fixture.files[0];
            let bound = fixture.bound.get(&source_file.file).unwrap();
            let module = bound.symbol(bound.source_file()).unwrap();

            let plan = fixture.plan_reexport(0, 0);

            assert!(plan.bindings.is_empty());
            assert_eq!(plan.module_specifier.file, source_file.file);
            assert!(bound.symbol(plan.declaration).is_none());
            assert!(fixture.store.symbol(module).unwrap().exports().is_none());
            assert_eq!(store_state(&fixture.store), before);
        }
    }

    #[test]
    fn trailing_named_import_and_reexport_commas_preserve_binder_owned_aliases() {
        let mut fixture = fixture(
            &[
                r#"import { forwarded as local, } from "./middle";"#,
                r#"export { value as forwarded, } from "./target";"#,
                "export const value: number = 1;",
            ],
            &[
                Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                },
                Route {
                    source: 1,
                    specifier: 0,
                    target: Some(2),
                },
            ],
        );
        let import = fixture.plan_import(0, 0);
        let reexport = fixture.plan_reexport(1, 0);
        let forwarded = direct_export(&fixture, 1, "forwarded");
        let value = direct_export(&fixture, 2, "value");

        assert_eq!(import.bindings[0].imported_text, "forwarded");
        assert_eq!(import.bindings[0].local_text, "local");
        assert_eq!(reexport.bindings[0].imported_text, "value");
        assert_eq!(reexport.bindings[0].exported_text, "forwarded");

        let resolved_import = resolve_all(&mut fixture, &import.bindings).unwrap();
        let resolved_reexport = resolve_all_reexports(&mut fixture, &reexport.bindings).unwrap();
        assert_eq!(resolved_import[0].immediate_target_symbol, forwarded);
        assert_eq!(resolved_import[0].target_symbol, value);
        assert_eq!(resolved_reexport[0].immediate_target_symbol, value);
        assert_eq!(resolved_reexport[0].target_symbol, value);

        let warm = store_state(&fixture.store);
        assert_eq!(
            resolve_all(&mut fixture, &import.bindings).unwrap(),
            resolved_import,
        );
        assert_eq!(
            resolve_all_reexports(&mut fixture, &reexport.bindings).unwrap(),
            resolved_reexport,
        );
        assert_eq!(store_state(&fixture.store), warm);
    }

    #[test]
    fn mixed_type_only_import_specifiers_preserve_separate_alias_phases() {
        let mut fixture = fixture(
            &[
                concat!(
                    "import { value, type Model as LocalModel, } from './target'; ",
                    "const copied = value; ",
                    "const model: LocalModel = { id: value };",
                ),
                "export const value: number = 1; export type Model = { id: number };",
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
        );
        let value_import = fixture.plan_import(0, 0);
        let type_import = fixture.plan_type_import(0, 0);
        let [value_binding] = value_import.bindings.as_slice() else {
            panic!("the mixed declaration must retain one value binding")
        };
        let [type_binding] = type_import.bindings.as_slice() else {
            panic!("the mixed declaration must retain one type-only binding")
        };
        assert_eq!(value_binding.local_text, "value");
        assert_eq!(type_binding.imported_text, "Model");
        assert_eq!(type_binding.local_text, "LocalModel");

        let values = resolve_all(&mut fixture, &value_import.bindings).unwrap();
        let types = resolve_all_types(&mut fixture, &type_import.bindings).unwrap();

        assert_eq!(values[0].target_symbol, direct_export(&fixture, 1, "value"));
        assert_eq!(types[0].target_symbol, direct_export(&fixture, 1, "Model"));
        assert!(
            fixture
                .store
                .alias_symbol_links(value_binding.alias_symbol)
                .unwrap()
                .type_only_declaration
                .is_none()
        );
        assert_eq!(
            fixture
                .store
                .alias_symbol_links(type_binding.alias_symbol)
                .and_then(|links| links.type_only_declaration),
            Some(type_binding.declaration),
        );

        let warm = store_state(&fixture.store);
        assert_eq!(
            resolve_all(&mut fixture, &value_import.bindings).unwrap(),
            values
        );
        assert_eq!(
            resolve_all_types(&mut fixture, &type_import.bindings).unwrap(),
            types,
        );
        assert_eq!(store_state(&fixture.store), warm);
    }

    #[test]
    fn export_star_chains_resolve_named_bindings_without_synthetic_aliases() {
        let mut fixture = fixture(
            &[
                "import { value as selected } from './middle'; const copied = selected;",
                "export * from './barrel';",
                "export * from './target';",
                "export const value: number = 1;",
            ],
            &[
                Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                },
                Route {
                    source: 1,
                    specifier: 0,
                    target: Some(2),
                },
                Route {
                    source: 2,
                    specifier: 0,
                    target: Some(3),
                },
            ],
        );
        let import = fixture.plan_import(0, 0);
        let middle = fixture.plan_reexport(1, 0);
        let barrel = fixture.plan_reexport(2, 0);
        assert!(middle.bindings.is_empty());
        assert!(barrel.bindings.is_empty());
        let target = direct_export(&fixture, 3, "value");

        let resolved = resolve_all(&mut fixture, &import.bindings).unwrap();

        assert_eq!(resolved[0].immediate_target_symbol, target);
        assert_eq!(resolved[0].target_symbol, target);
        for plan in [middle, barrel] {
            let bound = fixture.bound.get(&plan.declaration.file).unwrap();
            let star = bound.symbol(plan.declaration).unwrap();
            assert_eq!(
                fixture.store.symbol(star).unwrap().flags(),
                SymbolFlags::EXPORT_STAR
            );
            assert!(fixture.store.alias_symbol_links(star).is_none());
        }

        let warm = store_state(&fixture.store);
        assert_eq!(
            resolve_all(&mut fixture, &import.bindings).unwrap(),
            resolved
        );
        assert_eq!(store_state(&fixture.store), warm);
    }

