    #[test]
    fn package_self_namespace_imports_preserve_source_module_identity_cold_and_warm() {
        let mut fixture = fixture(
            &[concat!(
                "import * as namespace from 'package'; ",
                "export const value: number = 1; ",
                "const copied = namespace;",
            )],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(0),
            }],
        );
        let plan = fixture.plan_import(0, 0);
        let [binding] = plan.bindings.as_slice() else {
            panic!("the package self import must retain one namespace binding")
        };
        let source_file = fixture.files[0].file;
        let source = &fixture.files[0];
        let bound = fixture.bound.get(&source.file).unwrap();
        let module = bound.symbol(bound.source_file()).unwrap();
        let read = plan_source_import_identifier_read(
            &source.parsed.arena,
            bound,
            &fixture.store,
            binding,
            identifier_initializer(&fixture, 0, "namespace"),
            "namespace",
            binding.alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        assert_eq!(resolved[0].target_symbol, module);

        let prepared = prepare_one(&mut fixture, &resolved[0], &read).unwrap();

        assert_eq!(prepared.target_symbol, module);
        assert_eq!(prepared.target_declaration.file, source_file);
        let PreparedSourceImportTarget::ModuleNamespace { properties } = &prepared.target else {
            panic!("a package self import must retain its source module namespace")
        };
        let [property] = properties.as_slice() else {
            panic!("the package self import must expose its annotated export")
        };
        assert_eq!(property.name.as_utf8(), Some("value"));
        assert_eq!(property.value_symbol, direct_export(&fixture, 0, "value"));
        assert_eq!(
            property.type_,
            fixture.store.intrinsic_bootstrap().unwrap().number_type,
        );
        assert!(
            fixture
                .store
                .value_symbol_links(binding.alias_symbol)
                .is_none()
        );

        publish_for_test(&mut fixture.store, std::slice::from_ref(&prepared));
        let warm = (store_state(&fixture.store), fixture.store.symbol_len());
        assert_eq!(
            prepare_one(&mut fixture, &resolved[0], &read).unwrap(),
            prepared
        );
        assert_eq!(
            (store_state(&fixture.store), fixture.store.symbol_len()),
            warm
        );

        let source = parsed(concat!(
            "import * as namespace from 'package'; ",
            "export const value: number = 1; ",
            "const copied = namespace;",
        ));
        let file = FileId::new(9_780);
        let mut context = context_with_routes(
            &[(file, &source)],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(0),
            }],
        );

        context.check_source_file(file).unwrap();

        assert!(context.diagnostics().is_empty());
        assert_eq!(
            context_exported_type(&context, file, "value"),
            context.store().intrinsic_bootstrap().unwrap().number_type,
        );
        let warm = (store_state(context.store()), context.store().symbol_len());
        context.recheck_source_file(file).unwrap();
        assert_eq!(
            (store_state(context.store()), context.store().symbol_len()),
            warm
        );
    }

    #[test]
    fn package_self_namespace_exports_stage_recursive_shells_without_value_publication() {
        let text = concat!(
            "import * as namespace from 'package'; ",
            "export const value: number = 1; ",
            "export const forwarded = namespace;",
        );
        let mut fixture = fixture(
            &[text],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(0),
            }],
        );
        let import = fixture.plan_import(0, 0);
        let initializer = identifier_initializer(&fixture, 0, "namespace");
        let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
        let read = plan_source_import_identifier_read(
            &fixture.files[0].parsed.arena,
            bound,
            &fixture.store,
            &import.bindings[0],
            initializer,
            "namespace",
            import.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut fixture, &import.bindings).unwrap();
        let module = resolved[0].target_symbol;
        let forwarded = direct_export(&fixture, 0, "forwarded");

        let prepared = prepare_one(&mut fixture, &resolved[0], &read).unwrap();

        let PreparedSourceImportTarget::ModuleNamespace { properties } = &prepared.target else {
            panic!("a package self import must retain its staged namespace")
        };
        let [value, recursive] = properties.as_slice() else {
            panic!("the package namespace must expose its value and recursive export")
        };
        assert_eq!(value.name.as_utf8(), Some("value"));
        assert_eq!(
            value.type_,
            fixture.store.intrinsic_bootstrap().unwrap().number_type,
        );
        assert_eq!(recursive.name.as_utf8(), Some("forwarded"));
        assert_eq!(recursive.target_symbol, forwarded);
        assert_eq!(recursive.value_symbol, forwarded);
        assert_eq!(recursive.type_, prepared.type_);
        assert_eq!(
            fixture.store.type_payload(prepared.type_).unwrap().symbol(),
            Some(module),
        );
        for symbol in [module, forwarded, import.bindings[0].alias_symbol] {
            assert!(fixture.store.value_symbol_links(symbol).is_none());
        }

        let staged = (store_state(&fixture.store), fixture.store.symbol_len());
        assert_eq!(
            prepare_one(&mut fixture, &resolved[0], &read).unwrap(),
            prepared,
        );
        assert_eq!(
            (store_state(&fixture.store), fixture.store.symbol_len()),
            staged,
        );
        let publications = preflight_prepared_source_import_publications(
            &fixture.store,
            std::slice::from_ref(&prepared),
        )
        .unwrap();
        assert_eq!(publications.len(), 2);
        for symbol in [module, forwarded, import.bindings[0].alias_symbol] {
            assert!(fixture.store.value_symbol_links(symbol).is_none());
        }

        let source = parsed(text);
        let file = FileId::new(10_630);
        let mut context = context_with_routes(
            &[(file, &source)],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(0),
            }],
        );

        context.check_source_file(file).unwrap();

        let (_, bound) = context.file(file).unwrap();
        let module = bound.symbol(bound.source_file()).unwrap();
        let forwarded = context_exported_type(&context, file, "forwarded");
        assert_eq!(
            context.store().type_payload(forwarded).unwrap().symbol(),
            Some(module),
        );
        assert_eq!(
            context_exported_type(&context, file, "value"),
            context.store().intrinsic_bootstrap().unwrap().number_type,
        );
        assert!(context.diagnostics().is_empty());

        let warm = (store_state(context.store()), context.store().symbol_len());
        context.recheck_source_file(file).unwrap();
        assert_eq!(
            (store_state(context.store()), context.store().symbol_len()),
            warm,
        );
    }

    #[test]
    fn package_self_namespace_array_exports_do_not_capture_global_array_identity() {
        let mut fixture = fixture_with_default_library_files(
            &[
                concat!(
                    "import * as type from 'package'; ",
                    "export const Array: number = 1; ",
                    "export const main = type;",
                ),
                concat!(
                    "interface Array<T> { length: number; } ",
                    "declare var Array: any; ",
                    "interface ReadonlyArray<T> {}",
                ),
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(0),
            }],
            &[CanonicalModuleState::External, CanonicalModuleState::Script],
            &[1],
        );
        let import = fixture.plan_import(0, 0);
        let initializer = identifier_initializer(&fixture, 0, "type");
        let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
        let read = plan_source_import_identifier_read(
            &fixture.files[0].parsed.arena,
            bound,
            &fixture.store,
            &import.bindings[0],
            initializer,
            "type",
            import.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut fixture, &import.bindings).unwrap();
        let module = resolved[0].target_symbol;
        let exported_array = direct_export(&fixture, 0, "Array");
        let global_array = fixture
            .store
            .intrinsic_bootstrap()
            .and_then(|bootstrap| fixture.store.symbol_table(bootstrap.globals))
            .and_then(|globals| globals.get_source("Array"))
            .and_then(|symbol| fixture.store.get_merged_symbol(symbol))
            .unwrap();
        assert_ne!(exported_array, global_array);

        let prepared = prepare_one(&mut fixture, &resolved[0], &read).unwrap();

        let PreparedSourceImportTarget::ModuleNamespace { properties } = &prepared.target else {
            panic!("the package self import must retain its source namespace")
        };
        let [array, main] = properties.as_slice() else {
            panic!("the package namespace must retain its Array export and main self reference")
        };
        assert_eq!(array.name.as_utf8(), Some("Array"));
        assert_eq!(array.target_symbol, exported_array);
        assert_eq!(
            array.type_,
            fixture.store.intrinsic_bootstrap().unwrap().number_type,
        );
        assert_eq!(main.name.as_utf8(), Some("main"));
        assert_eq!(main.type_, prepared.type_);
        assert_eq!(
            fixture.store.type_payload(prepared.type_).unwrap().symbol(),
            Some(module),
        );
        assert_eq!(
            fixture
                .store
                .type_payload(fixture.global_types.array_type)
                .and_then(TypeRecord::symbol),
            Some(global_array),
        );
        assert!(fixture.store.value_symbol_links(module).is_none());
        assert!(
            fixture
                .store
                .value_symbol_links(import.bindings[0].alias_symbol)
                .is_none()
        );

        let warm = (store_state(&fixture.store), fixture.store.symbol_len());
        assert_eq!(
            prepare_one(&mut fixture, &resolved[0], &read).unwrap(),
            prepared,
        );
        assert_eq!(
            (store_state(&fixture.store), fixture.store.symbol_len()),
            warm,
        );
    }

    #[test]
    fn recursive_namespace_imports_check_consumers_before_providers() {
        let consumer = parsed(concat!(
            "import * as provider from './provider'; ",
            "export const copied = provider;",
        ));
        let provider = parsed(concat!(
            "import * as namespace from './provider'; ",
            "export const forwarded = namespace;",
        ));
        let consumer_file = FileId::new(10_710);
        let provider_file = FileId::new(10_711);
        let mut context = context_with_routes(
            &[(consumer_file, &consumer), (provider_file, &provider)],
            &[
                Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                },
                Route {
                    source: 1,
                    specifier: 0,
                    target: Some(1),
                },
            ],
        );

        context.check_source_file(consumer_file).unwrap();

        let copied = context_exported_type(&context, consumer_file, "copied");
        let (_, bound) = context.file(provider_file).unwrap();
        let module = bound.symbol(bound.source_file()).unwrap();
        let forwarded = context.store().symbol(module).unwrap().exports().unwrap();
        let forwarded = context
            .store()
            .symbol_table(forwarded)
            .unwrap()
            .get_source("forwarded")
            .unwrap();
        assert_eq!(
            context.store().type_payload(copied).unwrap().symbol(),
            Some(module)
        );
        assert!(context.store().value_symbol_links(forwarded).is_none());

        context.check_source_file(provider_file).unwrap();

        assert_eq!(
            context_exported_type(&context, provider_file, "forwarded"),
            copied
        );
        assert!(context.diagnostics().is_empty());
        let warm = (store_state(context.store()), context.store().symbol_len());
        context.recheck_source_file(consumer_file).unwrap();
        context.recheck_source_file(provider_file).unwrap();
        assert_eq!(
            (store_state(context.store()), context.store().symbol_len()),
            warm
        );
    }

