    #[test]
    fn cold_and_warm_direct_and_renamed_imports_type_only_used_bindings() {
        let mut fixture = fixture(
            &[
                r#"
                    import { numberValue, textValue as localText } from "./target";
                    const result: string = localText;
                "#,
                r#"
                    export const numberValue: number = 1;
                    export const textValue: string = "ok";
                "#,
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
        );
        let plan = fixture.plan_import(0, 0);
        assert_eq!(plan.bindings.len(), 2);
        assert_eq!(plan.bindings[1].imported_text, "textValue");
        assert_eq!(plan.bindings[1].local_text, "localText");

        let read = identifier_initializer(&fixture, 0, "localText");
        let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
        let planned_read = plan_source_import_identifier_read(
            &fixture.files[0].parsed.arena,
            bound,
            &fixture.store,
            &plan.bindings[1],
            read,
            "localText",
            plan.bindings[1].alias_symbol,
        )
        .unwrap();
        assert_eq!(planned_read.resolved_symbol, plan.bindings[1].alias_symbol);
        assert_eq!(planned_read.value_symbol, plan.bindings[1].alias_symbol);

        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        assert_eq!(resolved.len(), 2);
        let prepared = vec![prepare_one(&mut fixture, &resolved[1], &planned_read).unwrap()];
        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        assert_eq!(prepared[0].type_, bootstrap.string_type);
        assert_eq!(
            fixture
                .store
                .value_symbol_links(resolved[0].binding.alias_symbol),
            None,
            "an unused binding resolves but is never value-typed"
        );
        assert_eq!(
            fixture.store.value_symbol_links(resolved[0].target_symbol),
            None
        );
        for value in &prepared {
            assert_eq!(fixture.store.value_symbol_links(value.target_symbol), None);
            assert_eq!(
                fixture.store.value_symbol_links(value.binding.alias_symbol),
                None
            );
        }
        let publications =
            preflight_prepared_source_import_publications(&fixture.store, &prepared).unwrap();
        assert_eq!(publications.len(), 2);
        assert_eq!(
            fixture
                .store
                .value_symbol_links(resolved[0].binding.alias_symbol),
            None,
            "preflight itself performs no writes"
        );
        publish_for_test(&mut fixture.store, &prepared);
        for value in &prepared {
            assert_eq!(
                fixture
                    .store
                    .value_symbol_links(value.target_symbol)
                    .and_then(|links| links.resolved_type),
                Some(value.type_)
            );
            assert_eq!(
                fixture
                    .store
                    .value_symbol_links(value.binding.alias_symbol)
                    .and_then(|links| links.resolved_type),
                Some(value.type_)
            );
        }

        assert_eq!(
            fixture
                .store
                .value_symbol_links(resolved[0].binding.alias_symbol),
            None
        );
        assert_eq!(
            fixture.store.value_symbol_links(resolved[0].target_symbol),
            None
        );

        let warm_resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        assert_eq!(warm_resolved, resolved);
        let warm = vec![prepare_one(&mut fixture, &warm_resolved[1], &planned_read).unwrap()];
        assert_eq!(warm, prepared);
        publish_for_test(&mut fixture.store, &warm);
    }

    #[test]
    fn default_arrow_import_preserves_owners_and_cold_body_through_warm_replay() {
        let mut fixture = fixture(
            &[
                "import identity from './target'; const copied = identity;",
                "export default <T>(value: T): T => value;",
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
        );
        let plan = fixture.plan_import(0, 0);
        let read_node = identifier_initializer(&fixture, 0, "identity");
        let read = plan_source_import_identifier_read(
            &fixture.files[0].parsed.arena,
            fixture.bound.get(&fixture.files[0].file).unwrap(),
            &fixture.store,
            &plan.bindings[0],
            read_node,
            "identity",
            plan.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap().remove(0);
        let prepared = prepare_one(&mut fixture, &resolved, &read).unwrap();
        let PreparedSourceImportTarget::DefaultArrow { export, signature } = &prepared.target
        else {
            panic!("the direct default import retains its arrow export proof")
        };
        let export = export.as_ref().clone();
        let signature = *signature;
        assert_eq!(prepared.target_symbol, export.export_symbol);
        assert_eq!(prepared.target_declaration, export.declaration);
        assert_ne!(export.export_symbol, export.callable.owner_symbol);
        assert_eq!(
            fixture.store.symbol(export.export_symbol).unwrap().flags(),
            SymbolFlags::PROPERTY
        );
        assert_eq!(
            fixture
                .store
                .symbol(export.callable.owner_symbol)
                .unwrap()
                .flags(),
            SymbolFlags::FUNCTION
        );
        let signature_record = fixture.store.signature(signature).unwrap();
        assert_eq!(signature_record.type_parameters().len(), 1);
        assert_eq!(
            signature_record.resolved_return_type(),
            Some(signature_record.type_parameters()[0])
        );
        assert_eq!(
            fixture
                .store
                .source_callable_type_for_owner(export.callable.owner_symbol),
            Some(prepared.type_)
        );
        assert!(fixture.store.type_node_links(export.expression).is_none());
        assert!(
            fixture
                .store
                .value_symbol_links(export.export_symbol)
                .is_none()
        );
        assert!(
            fixture
                .store
                .value_symbol_links(plan.bindings[0].alias_symbol)
                .is_none()
        );
        let source = super::super::SourceFileRef::new(
            fixture.store.id(),
            fixture
                .bound
                .get(&fixture.files[1].file)
                .unwrap()
                .source_file(),
        );
        assert!(fixture.store.contains_source_file(source));
        assert!(
            fixture
                .store
                .source_file_links(source)
                .is_none_or(|links| !links.type_checked)
        );
        let before = (store_state(&fixture.store), fixture.store.signature_len());
        assert_eq!(
            preflight_prepared_source_import_publications(
                &fixture.store,
                std::slice::from_ref(&prepared)
            ),
            Err(invariant(SourceImportInvariant::PreparedStateChanged(
                plan.bindings[0].alias_symbol
            ))),
        );
        assert_eq!(
            (store_state(&fixture.store), fixture.store.signature_len()),
            before
        );

        let publications = {
            let host = DeclaredTypeHost::new_after_global_merge(
                fixture
                    .files
                    .iter()
                    .map(|file| (&file.parsed.arena, fixture.bound.get(&file.file).unwrap())),
                GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
            )
            .unwrap();
            preflight_prepared_source_import_publications_with_host(
                &fixture.store,
                &host,
                &fixture.global_types,
                std::slice::from_ref(&prepared),
            )
            .unwrap()
        };
        for publication in publications {
            assert!(
                fixture
                    .store
                    .set_value_symbol_links(publication.symbol, publication.links)
            );
        }
        let warm_state = (store_state(&fixture.store), fixture.store.signature_len());
        let warm = prepare_one(&mut fixture, &resolved, &read).unwrap();
        assert_eq!(warm, prepared);
        assert_eq!(
            (store_state(&fixture.store), fixture.store.signature_len()),
            warm_state
        );
        assert!(fixture.store.type_node_links(export.expression).is_none());
        assert!(
            fixture
                .store
                .source_file_links(source)
                .is_none_or(|links| !links.type_checked)
        );
        for symbol in [
            export.export_symbol,
            export.callable.owner_symbol,
            plan.bindings[0].alias_symbol,
        ] {
            let links = fixture.store.value_symbol_links(symbol).unwrap();
            assert_eq!(links.resolved_type, Some(prepared.type_));
            assert!(!links.function_or_constructor_checked);
        }
    }

    #[test]
    fn default_arrow_import_rejects_changed_default_entry_cold_and_warm() {
        for warm in [false, true] {
            let mut fixture = fixture(
                &[
                    "import identity from './target'; const copied = identity;",
                    "export default <T>(value: T): T => value;",
                ],
                &[Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                }],
            );
            let plan = fixture.plan_import(0, 0);
            let read_node = identifier_initializer(&fixture, 0, "identity");
            let read = plan_source_import_identifier_read(
                &fixture.files[0].parsed.arena,
                fixture.bound.get(&fixture.files[0].file).unwrap(),
                &fixture.store,
                &plan.bindings[0],
                read_node,
                "identity",
                plan.bindings[0].alias_symbol,
            )
            .unwrap();
            let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap().remove(0);
            let export = {
                let host = DeclaredTypeHost::new_after_global_merge(
                    fixture
                        .files
                        .iter()
                        .map(|file| (&file.parsed.arena, fixture.bound.get(&file.file).unwrap())),
                    GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
                )
                .unwrap();
                plan_source_import_default_arrow_export(
                    &fixture.store,
                    &host,
                    &fixture.global_types,
                    &resolved,
                )
                .unwrap()
                .unwrap()
            };
            let prepared = warm.then(|| prepare_one(&mut fixture, &resolved, &read).unwrap());
            if let Some(prepared) = &prepared {
                let publications = {
                    let host = DeclaredTypeHost::new_after_global_merge(
                        fixture.files.iter().map(|file| {
                            (&file.parsed.arena, fixture.bound.get(&file.file).unwrap())
                        }),
                        GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
                    )
                    .unwrap();
                    preflight_prepared_source_import_publications_with_host(
                        &fixture.store,
                        &host,
                        &fixture.global_types,
                        std::slice::from_ref(prepared),
                    )
                    .unwrap()
                };
                for publication in publications {
                    assert!(
                        fixture
                            .store
                            .set_value_symbol_links(publication.symbol, publication.links)
                    );
                }
            }
            let exports = fixture
                .store
                .symbol(export.module_symbol)
                .unwrap()
                .exports()
                .unwrap();
            assert_eq!(
                fixture.store.insert_symbol(
                    exports,
                    EscapedName::internal(InternalSymbolName::Default),
                    export.callable.owner_symbol,
                ),
                Some(Some(export.export_symbol))
            );
            let poisoned = (
                store_state(&fixture.store),
                fixture.store.signature_len(),
                fixture
                    .store
                    .value_symbol_links(export.export_symbol)
                    .cloned(),
                fixture
                    .store
                    .value_symbol_links(export.callable.owner_symbol)
                    .cloned(),
                fixture
                    .store
                    .value_symbol_links(plan.bindings[0].alias_symbol)
                    .cloned(),
                fixture.store.signature_links(export.expression).cloned(),
                fixture.store.type_node_links(export.expression).cloned(),
            );
            for _ in 0..2 {
                let expected = Err(invariant(SourceImportInvariant::InvalidTargetLinks(
                    export.export_symbol,
                )));
                assert_eq!(prepare_one(&mut fixture, &resolved, &read), expected);
                if let Some(prepared) = &prepared {
                    let host = DeclaredTypeHost::new_after_global_merge(
                        fixture.files.iter().map(|file| {
                            (&file.parsed.arena, fixture.bound.get(&file.file).unwrap())
                        }),
                        GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
                    )
                    .unwrap();
                    assert_eq!(
                        preflight_prepared_source_import_publications_with_host(
                            &fixture.store,
                            &host,
                            &fixture.global_types,
                            std::slice::from_ref(prepared),
                        ),
                        Err(invariant(SourceImportInvariant::InvalidTargetLinks(
                            export.export_symbol
                        )))
                    );
                }
                assert_eq!(
                    fixture
                        .store
                        .symbol_table(exports)
                        .unwrap()
                        .get(InternalSymbolName::Default.as_ref()),
                    Some(export.callable.owner_symbol)
                );
                assert_eq!(
                    (
                        store_state(&fixture.store),
                        fixture.store.signature_len(),
                        fixture
                            .store
                            .value_symbol_links(export.export_symbol)
                            .cloned(),
                        fixture
                            .store
                            .value_symbol_links(export.callable.owner_symbol)
                            .cloned(),
                        fixture
                            .store
                            .value_symbol_links(plan.bindings[0].alias_symbol)
                            .cloned(),
                        fixture.store.signature_links(export.expression).cloned(),
                        fixture.store.type_node_links(export.expression).cloned(),
                    ),
                    poisoned
                );
            }
            assert_eq!(
                fixture.store.insert_symbol(
                    exports,
                    EscapedName::internal(InternalSymbolName::Default),
                    export.export_symbol,
                ),
                Some(Some(export.callable.owner_symbol))
            );
            let restored = prepare_one(&mut fixture, &resolved, &read).unwrap();
            if let Some(prepared) = prepared {
                assert_eq!(restored, prepared);
                assert_eq!(
                    (store_state(&fixture.store), fixture.store.signature_len()),
                    (poisoned.0, poisoned.1)
                );
            }
        }
    }

    #[test]
    fn ambient_method_import_retains_overloads_and_keeps_unused_members_cold() {
        let mut fixture = ambient_method_import_fixture();
        let plan = fixture.plan_import(0, 0);
        let cold = store_state(&fixture.store);
        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        assert_eq!(fixture.store.type_len(), cold.0);
        assert_eq!(resolved[0].target_symbol, resolved[1].target_symbol);
        for binding in &resolved {
            let proof = binding.ambient_method.as_ref().unwrap();
            assert_eq!(proof.alias_symbol(), binding.binding.alias_symbol);
            assert_eq!(proof.method_symbol(), binding.target_symbol);
            assert_eq!(
                fixture.store.value_symbol_links(binding.target_symbol),
                None
            );
            assert_eq!(
                fixture
                    .store
                    .value_symbol_links(binding.binding.alias_symbol),
                None
            );
        }

        let prepared = prepare_ambient_method_import(&mut fixture, &resolved[0]).unwrap();
        let PreparedSourceImportTarget::AmbientMethod(method) = &prepared.target else {
            panic!("expected the native ambient method target");
        };
        assert_eq!(method.method.methods.len(), 2);
        assert_eq!(
            prepared.target_declaration,
            method.source.method_declaration()
        );
        assert_eq!(
            fixture.store.source_callable_provenance(prepared.type_),
            None
        );
        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        let expected = [bootstrap.string_type, bootstrap.number_type];
        for (overload, expected) in method.method.methods.iter().zip(expected) {
            let signature = fixture
                .store
                .signature_links(overload.declaration)
                .unwrap()
                .resolved_signature
                .signature()
                .unwrap();
            let record = fixture.store.signature(signature).unwrap();
            assert_eq!(record.declaration(), Some(overload.declaration));
            assert_eq!(record.resolved_return_type(), Some(expected));
            assert_eq!(record.parameters(), &[overload.parameters[0].symbol]);
            assert_eq!(
                fixture.store.interface_method_linked_type(signature),
                Some(prepared.type_)
            );
            assert_eq!(
                fixture.store.callable_signature_parameter_types(signature),
                Some(&[expected][..])
            );
        }
        let recursive = fixture
            .store
            .symbol_table(method.method.members.unwrap())
            .unwrap()
            .get_source("recursive")
            .unwrap();
        assert_eq!(fixture.store.value_symbol_links(recursive), None);
        assert_eq!(
            fixture.store.value_symbol_links(resolved[2].target_symbol),
            None
        );
        for binding in &resolved {
            assert_eq!(
                fixture
                    .store
                    .value_symbol_links(binding.binding.alias_symbol),
                None
            );
        }
        assert!(
            prepare_value_links(
                &fixture.store,
                prepared.target_symbol,
                prepared.type_,
                false
            )
            .is_err()
        );
        let before = (store_state(&fixture.store), fixture.store.signature_len());
        assert_eq!(
            preflight_prepared_source_import_publications(
                &fixture.store,
                std::slice::from_ref(&prepared)
            ),
            Err(invariant(SourceImportInvariant::PreparedStateChanged(
                prepared.binding.alias_symbol
            )))
        );
        let publications = preflight_ambient_method_import(&fixture, &prepared).unwrap();
        assert_eq!(publications.len(), 2);
        assert_eq!(
            (store_state(&fixture.store), fixture.store.signature_len()),
            before
        );
        for publication in publications {
            assert!(
                fixture
                    .store
                    .set_value_symbol_links(publication.symbol, publication.links)
            );
        }
        let warm = (store_state(&fixture.store), fixture.store.signature_len());
        assert_eq!(resolve_all(&mut fixture, &plan.bindings).unwrap(), resolved);
        assert_eq!(
            prepare_ambient_method_import(&mut fixture, &resolved[0]).unwrap(),
            prepared
        );
        preflight_ambient_method_import(&fixture, &prepared).unwrap();
        assert_eq!(
            (store_state(&fixture.store), fixture.store.signature_len()),
            warm
        );
        assert_eq!(fixture.store.value_symbol_links(recursive), None);
        assert_eq!(
            fixture.store.value_symbol_links(resolved[2].target_symbol),
            None
        );
        assert_eq!(
            fixture
                .store
                .value_symbol_links(resolved[1].binding.alias_symbol),
            None
        );
        assert_eq!(
            fixture
                .store
                .value_symbol_links(resolved[2].binding.alias_symbol),
            None
        );
    }

    #[test]
    fn ambient_method_import_rejects_changed_native_graph_before_alias_publication() {
        for poison in 0..6 {
            let mut fixture = ambient_method_import_fixture();
            let plan = fixture.plan_import(0, 0);
            let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
            let prepared = prepare_ambient_method_import(&mut fixture, &resolved[0]).unwrap();
            let PreparedSourceImportTarget::AmbientMethod(method) = &prepared.target else {
                panic!("expected the native ambient method target");
            };
            let declaration = method.method.methods[0].declaration;
            let parameter = method.method.methods[0].parameters[0].symbol;
            let method_links = fixture
                .store
                .value_symbol_links(prepared.target_symbol)
                .cloned()
                .unwrap();
            let parameter_links = fixture
                .store
                .value_symbol_links(parameter)
                .cloned()
                .unwrap();
            let signature_links = fixture.store.signature_links(declaration).cloned().unwrap();
            let signature = signature_links.resolved_signature.signature().unwrap();
            let second_signature = fixture
                .store
                .signature_links(method.method.methods[1].declaration)
                .unwrap()
                .resolved_signature
                .signature()
                .unwrap();
            let signature_record = fixture.store.signature(signature).unwrap();
            let signature_flags = signature_record.flags();
            let signature_return_type = signature_record.resolved_return_type();
            let number = fixture.store.intrinsic_bootstrap().unwrap().number_type;
            match poison {
                0 => {
                    let mut links = method_links.clone();
                    links.resolved_type = Some(number);
                    assert!(
                        fixture
                            .store
                            .set_value_symbol_links(prepared.target_symbol, links)
                    );
                }
                1 => {
                    let mut links = parameter_links.clone();
                    links.write_type = Some(number);
                    assert!(fixture.store.set_value_symbol_links(parameter, links));
                }
                2 => assert!(fixture.store.set_signature_flags(
                    signature,
                    super::super::signatures::SignatureFlags::CONSTRUCT
                )),
                3 => assert!(
                    fixture
                        .store
                        .set_signature_resolved_return_type(signature, Some(number))
                ),
                4 => assert!(
                    fixture
                        .store
                        .set_type_symbol(prepared.type_, Some(resolved[2].target_symbol))
                ),
                5 => {
                    let mut links = signature_links.clone();
                    links.resolved_signature =
                        super::super::ResolvedSignatureState::Resolved(second_signature);
                    assert!(fixture.store.set_signature_links(declaration, links));
                }
                _ => unreachable!(),
            }
            let before = (store_state(&fixture.store), fixture.store.signature_len());
            for _ in 0..2 {
                assert!(
                    prepare_ambient_method_import(&mut fixture, &resolved[0]).is_err(),
                    "poison={poison}"
                );
                assert!(
                    preflight_ambient_method_import(&fixture, &prepared).is_err(),
                    "poison={poison}"
                );
                assert_eq!(
                    (store_state(&fixture.store), fixture.store.signature_len()),
                    before,
                    "poison={poison}"
                );
                assert_eq!(
                    fixture
                        .store
                        .value_symbol_links(prepared.binding.alias_symbol),
                    None
                );
            }
            assert!(
                fixture
                    .store
                    .set_value_symbol_links(prepared.target_symbol, method_links)
            );
            assert!(
                fixture
                    .store
                    .set_value_symbol_links(parameter, parameter_links)
            );
            assert!(
                fixture
                    .store
                    .set_signature_flags(signature, signature_flags)
            );
            assert!(
                fixture
                    .store
                    .set_signature_resolved_return_type(signature, signature_return_type)
            );
            assert!(
                fixture
                    .store
                    .set_type_symbol(prepared.type_, Some(prepared.target_symbol))
            );
            assert!(
                fixture
                    .store
                    .set_signature_links(declaration, signature_links)
            );
            assert_eq!(
                prepare_ambient_method_import(&mut fixture, &resolved[0]).unwrap(),
                prepared
            );
            preflight_ambient_method_import(&fixture, &prepared).unwrap();
            assert_eq!(
                fixture
                    .store
                    .value_symbol_links(prepared.binding.alias_symbol),
                None
            );
        }
    }

    #[test]
    fn ambient_method_import_rejects_a_proof_for_another_alias_or_changed_native_plan() {
        let mut fixture = ambient_method_import_fixture();
        let plan = fixture.plan_import(0, 0);
        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        let mut changed = resolved[0].clone();
        changed.ambient_method = resolved[1].ambient_method.clone();
        let cold = (store_state(&fixture.store), fixture.store.signature_len());
        assert_eq!(
            prepare_ambient_method_import(&mut fixture, &changed),
            Err(invariant(SourceImportInvariant::InvalidAliasLinks(
                resolved[0].binding.alias_symbol
            )))
        );
        assert_eq!(
            (store_state(&fixture.store), fixture.store.signature_len()),
            cold
        );
        assert_eq!(
            fixture.store.value_symbol_links(resolved[0].target_symbol),
            None
        );

        let prepared = prepare_ambient_method_import(&mut fixture, &resolved[0]).unwrap();
        let before = (store_state(&fixture.store), fixture.store.signature_len());
        let mut changed = prepared.clone();
        changed.binding = resolved[1].binding.clone();
        assert!(preflight_ambient_method_import(&fixture, &changed).is_err());
        let mut changed = prepared.clone();
        let PreparedSourceImportTarget::AmbientMethod(method) = &mut changed.target else {
            panic!("expected the native ambient method target");
        };
        method.method.methods.pop();
        assert!(preflight_ambient_method_import(&fixture, &changed).is_err());
        assert_eq!(
            (store_state(&fixture.store), fixture.store.signature_len()),
            before
        );
        preflight_ambient_method_import(&fixture, &prepared).unwrap();
        for binding in &resolved {
            assert_eq!(
                fixture
                    .store
                    .value_symbol_links(binding.binding.alias_symbol),
                None
            );
        }
    }

    #[test]
    fn exported_generic_function_import_prepares_exact_callable_and_replays_warm() {
        let mut fixture = fixture(
            &[
                r#"
                    import { identity } from "./target";
                    const imported = identity;
                "#,
                r"
                    export function identity<T>(value: T): T { return value; }
                ",
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
        );
        let plan = fixture.plan_import(0, 0);
        let read = identifier_initializer(&fixture, 0, "identity");
        let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
        let planned_read = plan_source_import_identifier_read(
            &fixture.files[0].parsed.arena,
            bound,
            &fixture.store,
            &plan.bindings[0],
            read,
            "identity",
            plan.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        let [resolved] = resolved.as_slice() else {
            panic!("expected one import binding")
        };
        let target = direct_export(&fixture, 1, "identity");
        assert_eq!(resolved.target_symbol, target);

        let prepared = prepare_one(&mut fixture, resolved, &planned_read).unwrap();
        let PreparedSourceImportTarget::AnnotatedFunction { signature } = &prepared.target else {
            panic!("expected an annotated function target")
        };
        let signature = *signature;
        let signature_record = fixture.store.signature(signature).unwrap();
        let [type_parameter] = signature_record.type_parameters() else {
            panic!("expected one generic type parameter")
        };
        assert_eq!(
            signature_record.resolved_return_type(),
            Some(*type_parameter)
        );
        assert_eq!(
            fixture.store.source_callable_type_for_owner(target),
            Some(prepared.type_)
        );
        assert_eq!(
            fixture
                .store
                .value_symbol_links(target)
                .and_then(|links| links.resolved_type),
            Some(prepared.type_),
            "the target callable graph is a canonical lazy-query memo"
        );
        assert_eq!(
            fixture
                .store
                .value_symbol_links(plan.bindings[0].alias_symbol),
            None,
            "the importer alias remains deferred until final publication"
        );

        publish_for_test(&mut fixture.store, std::slice::from_ref(&prepared));
        assert_eq!(
            fixture
                .store
                .value_symbol_links(plan.bindings[0].alias_symbol)
                .and_then(|links| links.resolved_type),
            Some(prepared.type_)
        );
        let warm_state = store_state(&fixture.store);

        let warm_resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        assert_eq!(warm_resolved.as_slice(), std::slice::from_ref(resolved));
        let warm = prepare_one(&mut fixture, &warm_resolved[0], &planned_read).unwrap();
        assert_eq!(warm, prepared);
        assert_eq!(store_state(&fixture.store), warm_state);
        publish_for_test(&mut fixture.store, std::slice::from_ref(&warm));
    }

