    #[test]
    fn declaration_boolean_const_imports_preserve_exact_literals_cold_and_warm() {
        for (spelling, expected_value) in [("true", true), ("false", false)] {
            let mut fixture = fixture_with_declaration_files(
                &[
                    "import { value } from './target'; const copied = value;",
                    &format!("export const value = {spelling};"),
                ],
                &[Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                }],
                &[1],
            );
            let plan = fixture.plan_import(0, 0);
            let node = identifier_initializer(&fixture, 0, "value");
            let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
            let read = plan_source_import_identifier_read(
                &fixture.files[0].parsed.arena,
                bound,
                &fixture.store,
                &plan.bindings[0],
                node,
                "value",
                plan.bindings[0].alias_symbol,
            )
            .unwrap();
            let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();

            let prepared = prepare_one(&mut fixture, &resolved[0], &read).unwrap();

            assert!(matches!(
                &prepared.target,
                PreparedSourceImportTarget::DeclarationBooleanConst { value, .. }
                    if *value == expected_value
            ));
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            assert_eq!(
                prepared.type_,
                if expected_value {
                    bootstrap.true_type
                } else {
                    bootstrap.false_type
                },
            );
            assert_eq!(display_type(&fixture, prepared.type_), spelling);
            assert!(
                fixture
                    .store
                    .value_symbol_links(resolved[0].target_symbol)
                    .is_none()
            );

            publish_for_test(&mut fixture.store, std::slice::from_ref(&prepared));
            let warm = store_state(&fixture.store);
            assert_eq!(
                prepare_one(&mut fixture, &resolved[0], &read).unwrap(),
                prepared,
            );
            assert_eq!(store_state(&fixture.store), warm);
        }
    }

    #[test]
    fn declaration_namespaces_include_implicit_and_boolean_const_exports() {
        let mut fixture = fixture_with_declaration_files(
            &[
                "import * as values from './target'; const copied = values;",
                "export const label: string; export const enabled = true;",
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
            &[1],
        );
        let plan = fixture.plan_import(0, 0);
        let node = identifier_initializer(&fixture, 0, "values");
        let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
        let read = plan_source_import_identifier_read(
            &fixture.files[0].parsed.arena,
            bound,
            &fixture.store,
            &plan.bindings[0],
            node,
            "values",
            plan.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();

        let prepared = prepare_one(&mut fixture, &resolved[0], &read).unwrap();

        let PreparedSourceImportTarget::ModuleNamespace { properties } = &prepared.target else {
            panic!("expected an imported declaration namespace")
        };
        assert_eq!(properties.len(), 2);
        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        let label = properties
            .iter()
            .find(|property| property.name.as_utf8() == Some("label"))
            .unwrap();
        let enabled = properties
            .iter()
            .find(|property| property.name.as_utf8() == Some("enabled"))
            .unwrap();
        assert_eq!(label.type_, bootstrap.string_type);
        assert_eq!(enabled.type_, bootstrap.true_type);

        publish_for_test(&mut fixture.store, std::slice::from_ref(&prepared));
        let warm = store_state(&fixture.store);
        assert_eq!(
            prepare_one(&mut fixture, &resolved[0], &read).unwrap(),
            prepared,
        );
        assert_eq!(store_state(&fixture.store), warm);
    }

    #[test]
    fn declaration_boolean_const_import_rejects_poisoned_target_values() {
        let mut fixture = fixture_with_declaration_files(
            &[
                "import { value } from './target'; const copied = value;",
                "export const value = true;",
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
            &[1],
        );
        let plan = fixture.plan_import(0, 0);
        let node = identifier_initializer(&fixture, 0, "value");
        let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
        let read = plan_source_import_identifier_read(
            &fixture.files[0].parsed.arena,
            bound,
            &fixture.store,
            &plan.bindings[0],
            node,
            "value",
            plan.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
        let wrong = fixture.store.intrinsic_bootstrap().unwrap().false_type;
        assert!(fixture.store.set_value_symbol_links(
            resolved[0].target_symbol,
            ValueSymbolLinks {
                resolved_type: Some(wrong),
                ..ValueSymbolLinks::default()
            },
        ));
        let before = store_state(&fixture.store);

        assert!(matches!(
            prepare_one(&mut fixture, &resolved[0], &read),
            Err(SourceImportError::Invariant(
                SourceImportInvariant::CachedTypeMismatch { symbol, .. }
            )) if symbol == resolved[0].target_symbol
        ));
        assert_eq!(store_state(&fixture.store), before);
        assert!(
            fixture
                .store
                .value_symbol_links(plan.bindings[0].alias_symbol)
                .is_none()
        );
    }

    #[test]
    fn declaration_numeric_const_import_rejects_unsupported_initializer_shapes() {
        for target in [
            "export declare const value: number = 1;",
            "export declare const value;",
            "export const value = \"one\";",
            "export const value = -1;",
            "export const value = 1, another = 2;",
        ] {
            let mut fixture = fixture_with_declaration_files(
                &[
                    r#"
                        import { value } from "./target";
                        const result = value;
                    "#,
                    target,
                ],
                &[Route {
                    source: 0,
                    specifier: 0,
                    target: Some(1),
                }],
                &[1],
            );
            let plan = fixture.plan_import(0, 0);
            let read_node = identifier_initializer(&fixture, 0, "value");
            let bound = fixture.bound.get(&fixture.files[0].file).unwrap();
            let read = plan_source_import_identifier_read(
                &fixture.files[0].parsed.arena,
                bound,
                &fixture.store,
                &plan.bindings[0],
                read_node,
                "value",
                plan.bindings[0].alias_symbol,
            )
            .unwrap();
            let resolved = resolve_all(&mut fixture, &plan.bindings).unwrap();
            let before = store_state(&fixture.store);
            assert!(
                matches!(
                    prepare_one(&mut fixture, &resolved[0], &read),
                    Err(SourceImportError::Unsupported(_))
                ),
                "declaration initializer unexpectedly escaped its boundary: {target}",
            );
            assert_eq!(store_state(&fixture.store), before);
            assert!(
                fixture
                    .store
                    .value_symbol_links(resolved[0].target_symbol)
                    .is_none()
            );
            assert!(
                fixture
                    .store
                    .value_symbol_links(plan.bindings[0].alias_symbol)
                    .is_none()
            );
        }
    }

    #[test]
    fn unannotated_target_and_non_value_import_syntax_remain_explicit_boundaries() {
        let mut unannotated = fixture(
            &[
                r#"
                    import { value } from "./target";
                    const result = value;
                "#,
                r"export const value = 1;",
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
        );
        let plan = unannotated.plan_import(0, 0);
        let read_node = identifier_initializer(&unannotated, 0, "value");
        let bound = unannotated.bound.get(&unannotated.files[0].file).unwrap();
        let read = plan_source_import_identifier_read(
            &unannotated.files[0].parsed.arena,
            bound,
            &unannotated.store,
            &plan.bindings[0],
            read_node,
            "value",
            plan.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut unannotated, &plan.bindings).unwrap();
        let before = store_state(&unannotated.store);
        assert!(matches!(
            prepare_one(&mut unannotated, &resolved[0], &read),
            Err(SourceImportError::Unsupported(
                SourceImportUnsupported::MissingTargetAnnotation(_)
            ))
        ));
        assert_eq!(store_state(&unannotated.store), before);
        assert!(
            unannotated
                .store
                .value_symbol_links(resolved[0].target_symbol)
                .is_none()
        );
        assert!(
            unannotated
                .store
                .value_symbol_links(plan.bindings[0].alias_symbol)
                .is_none()
        );

        let mut unannotated_function = fixture(
            &[
                r#"
                    import { identity } from "./target";
                    const result = identity;
                "#,
                r"export function identity<T>(value: T) { return value; }",
            ],
            &[Route {
                source: 0,
                specifier: 0,
                target: Some(1),
            }],
        );
        let plan = unannotated_function.plan_import(0, 0);
        let read_node = identifier_initializer(&unannotated_function, 0, "identity");
        let bound = unannotated_function
            .bound
            .get(&unannotated_function.files[0].file)
            .unwrap();
        let read = plan_source_import_identifier_read(
            &unannotated_function.files[0].parsed.arena,
            bound,
            &unannotated_function.store,
            &plan.bindings[0],
            read_node,
            "identity",
            plan.bindings[0].alias_symbol,
        )
        .unwrap();
        let resolved = resolve_all(&mut unannotated_function, &plan.bindings).unwrap();
        let before = store_state(&unannotated_function.store);
        assert_eq!(
            prepare_one(&mut unannotated_function, &resolved[0], &read),
            Err(SourceImportError::Unsupported(
                SourceImportUnsupported::TargetSymbol {
                    alias: plan.bindings[0].alias_symbol,
                    target: resolved[0].target_symbol,
                    flags: SymbolFlags::FUNCTION,
                }
            ))
        );
        assert_eq!(store_state(&unannotated_function.store), before);
        assert_eq!(
            unannotated_function
                .store
                .value_symbol_links(plan.bindings[0].alias_symbol),
            None
        );
        assert_eq!(
            unannotated_function
                .store
                .value_symbol_links(resolved[0].target_symbol),
            None
        );

        let clause_only = fixture(
            &[
                r#"import type { value } from "./target";"#,
                r"export const value: number = 1;",
            ],
            &[],
        );
        let file = &clause_only.files[0];
        let bound = clause_only.bound.get(&file.file).unwrap();
        let declaration = file
            .parsed
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ImportDeclaration).then_some(node)
            })
            .unwrap();
        assert!(matches!(
            plan_top_level_named_value_import(
                &file.parsed.arena,
                bound,
                &clause_only.store,
                NodeRef::new(file.parsed.arena.id(), file.file, declaration),
            ),
            Err(SourceImportError::Unsupported(_))
        ));

        let specifier_only = fixture(
            &[
                r#"import { type value } from "./target";"#,
                r"export const value: number = 1;",
            ],
            &[],
        );
        assert!(specifier_only.plan_import(0, 0).bindings.is_empty());
        assert_eq!(specifier_only.plan_type_import(0, 0).bindings.len(), 1);
    }

